"""
OutputFormatter — renders SynthesisResult as narrative intelligence brief.
Zone-tagged prose, not tables. Zero LLM calls.
"""


class OutputFormatter:
    def format(self, result, strategic_insight=None, founder_context=None) -> str:
        si = strategic_insight or result.strategic_insight
        parts = [
            self._header(result, si),
            self._mechanism(result, si),
            self._landscape(result),
            self._critical_gaps(result),
            self._strategic_path(result, si),
        ]
        if si and (si.get("asymmetric_play") or si.get("kill_conditions") or si.get("proceed_conditions")):
            parts.append(self._asymmetric_edge(si))
        parts.append(self._meta(result))
        return "\n\n".join(p for p in parts if p)

    # ── Header ────────────────────────────────────────────────────────────────

    def _header(self, result, si) -> str:
        score = result.overall_score
        verdict_label = (
            "strong signal" if score >= 0.75
            else "moderate signal" if score >= 0.5
            else "weak signal" if score >= 0.3
            else "insufficient data"
        )
        k = result.facts_by_zone.get("K", 0)
        t = result.facts_by_zone.get("T", 0)
        unk = result.facts_by_zone.get("?", 0)
        total = max(result.facts_used, 1)
        zone_narrative = (
            f"{k} verified [K], {t} inferred [T], {unk} uncertain [?]"
            if (k + t + unk) > 0
            else "no zone data"
        )
        verdict_line = f"**Verdict:** {score:.0%} {verdict_label} | {zone_narrative}"
        if si and si.get("verdict"):
            verdict_line += f" | {si['verdict']}"
        return f"# Intelligence Brief: {result.query}\n\n{verdict_line}"

    # ── Mechanism ─────────────────────────────────────────────────────────────

    def _mechanism(self, result, si) -> str:
        lines = ["## Mechanism"]
        if si and si.get("causal_chain"):
            chain = si["causal_chain"]
            if isinstance(chain, list):
                lines.append(" → ".join(str(c) for c in chain) + ".")
            else:
                lines.append(str(chain))
        else:
            # Synthesize from dimensions: highest and lowest scored tell the story
            sorted_dims = sorted(result.dimension_scores.items(), key=lambda x: x[1].score)
            if sorted_dims:
                weak = sorted_dims[0]
                strong = sorted_dims[-1]
                weak_name, weak_ds = weak
                strong_name, strong_ds = strong
                lines.append(
                    f"The strongest evidence sits in **{strong_name}** [{strong_ds.zone_tag}] "
                    f"({strong_ds.fact_count} facts, {strong_ds.avg_confidence:.0%} avg confidence). "
                    f"The critical unknown is **{weak_name}** [{weak_ds.zone_tag}] — "
                    f"only {weak_ds.fact_count} facts at {weak_ds.avg_confidence:.0%} confidence, "
                    f"which is the primary bottleneck to a clear verdict."
                )
            else:
                lines.append("Insufficient dimension data to synthesize mechanism.")
        return "\n\n".join(lines)

    # ── Landscape ─────────────────────────────────────────────────────────────

    def _landscape(self, result) -> str:
        if not result.dimension_scores:
            return ""
        lines = ["## Landscape"]
        # Sort by ascending score: most critical gaps first
        sorted_dims = sorted(result.dimension_scores.items(), key=lambda x: x[1].score)
        prev_name = None
        for dim_name, ds in sorted_dims:
            status = (
                "well-covered" if ds.score >= 0.7
                else "partially mapped" if ds.score >= 0.4
                else "largely unknown"
            )
            sentence = (
                f"**{dim_name}** [{ds.zone_tag}] is {status} ({ds.score:.0%}, "
                f"{ds.fact_count} facts at {ds.avg_confidence:.0%} confidence)."
            )
            if ds.contradictions > 0:
                sentence += (
                    f" There {'is' if ds.contradictions == 1 else 'are'} "
                    f"{ds.contradictions} contradiction{'s' if ds.contradictions > 1 else ''} "
                    f"in this dimension — treat its signals as contested."
                )
            # Connect to previous dimension where logical (simple linkage hint)
            if prev_name and ds.score < 0.4:
                sentence += f" This gap is likely downstream of weak {prev_name} data."
            lines.append(sentence)
            prev_name = dim_name
        return "\n\n".join(lines)

    # ── Critical Gaps ─────────────────────────────────────────────────────────

    def _critical_gaps(self, result) -> str:
        if not result.gaps:
            return ""
        lines = ["## Critical Gaps"]
        for gap in result.gaps:
            risk_level = "high" if gap.priority >= 0.7 else "medium" if gap.priority >= 0.4 else "low"
            para = (
                f"**{gap.dimension}** ({risk_level} priority, coverage {gap.score:.0%}): "
                f"{gap.suggested_action} "
                f"Without this, any decision rests on incomplete ground — "
                f"the risk is {'material' if risk_level == 'high' else 'moderate'}."
            )
            lines.append(para)
        return "\n\n".join(lines)

    # ── Strategic Path ────────────────────────────────────────────────────────

    def _strategic_path(self, result, si) -> str:
        if not result.path and not (si and si.get("asymmetric_play")):
            return ""
        lines = ["## Strategic Path"]
        compound = si.get("compound_trap") if si else None
        if compound:
            lines.append(f"The compound asset being built here: **{compound}**")
        if result.path:
            narrative_parts = []
            for step in result.path:
                deps = ""
                if step.dependencies:
                    deps = f" (requires: {', '.join(step.dependencies)})"
                narrative_parts.append(
                    f"**Move {step.step_number}** — {step.action} [{step.zone_tag}] "
                    f"({step.confidence:.0%} confidence). {step.rationale}{deps}."
                )
            lines.append(" ".join(narrative_parts) if len(narrative_parts) == 1
                         else "\n\n".join(narrative_parts))
        return "\n\n".join(lines)

    # ── Asymmetric Edge ───────────────────────────────────────────────────────

    def _asymmetric_edge(self, si) -> str:
        lines = ["## Asymmetric Edge"]
        if si.get("asymmetric_play"):
            lines.append(f"**The play others miss:** {si['asymmetric_play']}")
        if si.get("proceed_conditions"):
            conds = si["proceed_conditions"]
            if isinstance(conds, list):
                lines.append("**Proceed when:** " + "; ".join(str(c) for c in conds) + ".")
            else:
                lines.append(f"**Proceed when:** {conds}")
        if si.get("kill_conditions"):
            conds = si["kill_conditions"]
            if isinstance(conds, list):
                lines.append("**Kill if:** " + "; ".join(str(c) for c in conds) + ".")
            else:
                lines.append(f"**Kill if:** {conds}")
        return "\n\n".join(lines)

    # ── Meta footer ───────────────────────────────────────────────────────────

    def _meta(self, result) -> str:
        k = result.facts_by_zone.get("K", 0)
        t = result.facts_by_zone.get("T", 0)
        unk = result.facts_by_zone.get("?", 0)
        zone_str = f"K={k} T={t} ?={unk}"
        return (
            f"---\n"
            f"*{result.query_type} | {len(result.dimension_scores)} dimensions | "
            f"{result.facts_used} facts [{zone_str}] | {result.llm_calls_made} reasoning calls*"
        )

"""
Tests for OutputFormatter narrative rewrite.
Verifies: no dimension tables, zone tags inline, strategic insight integration,
graceful degradation, gap implications, path narrative, backward compatibility.
"""

import pytest

from ..dimension_scorer import DimensionScore
from ..gap_analyzer import GapReport
from ..output_formatter import OutputFormatter
from ..path_generator import PathStep
from ..synthesis_engine import SynthesisResult


# ── Fixtures ──────────────────────────────────────────────────────────────────


def _dim(name="market_size", score=0.8, fact_count=5, avg_conf=0.75, contradictions=0, zone="K"):
    return DimensionScore(
        dimension=name,
        score=score,
        fact_count=fact_count,
        avg_confidence=avg_conf,
        contradictions=contradictions,
        zone_tag=zone,
    )


def _gap(dim="competition", priority=0.8, score=0.2, action="Research top 3 competitors"):
    return GapReport(
        dimension=dim,
        score=score,
        missing_queries=["who are competitors?", "market share?"],
        priority=priority,
        suggested_action=action,
    )


def _step(n=1, action="Validate demand", rationale="No buyers = no business", conf=0.85, deps=None, zone="K"):
    return PathStep(
        step_number=n,
        action=action,
        rationale=rationale,
        confidence=conf,
        dependencies=deps or [],
        zone_tag=zone,
    )


def _result(
    query="Should I enter the coffee market?",
    query_type="market_entry",
    score=0.62,
    dim_scores=None,
    gaps=None,
    path=None,
    facts_used=18,
    facts_by_zone=None,
    llm_calls=3,
    strategic_insight=None,
):
    return SynthesisResult(
        query=query,
        query_type=query_type,
        overall_score=score,
        dimension_scores=dim_scores or {"market_size": _dim()},
        gaps=gaps or [],
        path=path or [],
        facts_used=facts_used,
        facts_by_zone=facts_by_zone or {"K": 10, "T": 6, "?": 2},
        llm_calls_made=llm_calls,
        strategic_insight=strategic_insight,
    )


# ── 1. Basic narrative — no table headers ─────────────────────────────────────


class TestNoTableOutput:
    def setup_method(self):
        self.fmt = OutputFormatter()

    def test_no_dimension_table_header(self):
        out = self.fmt.format(_result())
        assert "| Dimension |" not in out

    def test_no_pipe_rows(self):
        out = self.fmt.format(_result())
        # Allow the meta footer dashes but no markdown table pipe rows
        pipe_lines = [ln for ln in out.splitlines() if ln.strip().startswith("|")]
        assert len(pipe_lines) == 0, f"Found table rows: {pipe_lines}"

    def test_has_intelligence_brief_header(self):
        out = self.fmt.format(_result(query="Test query"))
        assert "# Intelligence Brief: Test query" in out

    def test_verdict_line_present(self):
        out = self.fmt.format(_result(score=0.75))
        assert "**Verdict:**" in out
        assert "strong signal" in out

    def test_verdict_weak_signal(self):
        out = self.fmt.format(_result(score=0.2))
        assert "insufficient data" in out

    def test_verdict_moderate_signal(self):
        out = self.fmt.format(_result(score=0.55))
        assert "moderate signal" in out

    def test_zone_distribution_in_verdict(self):
        out = self.fmt.format(_result(facts_by_zone={"K": 5, "T": 3, "?": 1}))
        assert "[K]" in out
        assert "[T]" in out
        assert "[?]" in out

    def test_meta_footer_present(self):
        out = self.fmt.format(_result())
        assert "---" in out
        assert "reasoning calls" in out


# ── 2. Strategic insight integration ─────────────────────────────────────────


class TestStrategicInsightIntegration:
    def setup_method(self):
        self.fmt = OutputFormatter()
        self.si = {
            "causal_chain": ["Demand exists", "Supply fragmented", "Margin available"],
            "asymmetric_play": "Lock in roaster contracts before retail enters",
            "compound_trap": "Roaster relationship network",
            "verdict": "GO with capital constraint",
            "kill_conditions": ["commodity price >40% COGS", "retail giants enter"],
            "proceed_conditions": ["gross margin >35%", "repeat order rate >60%"],
        }

    def test_causal_chain_rendered_as_narrative(self):
        out = self.fmt.format(_result(strategic_insight=self.si))
        assert "Demand exists" in out
        assert "→" in out  # chain connector

    def test_verdict_from_strategic_insight_appended(self):
        out = self.fmt.format(_result(strategic_insight=self.si))
        assert "GO with capital constraint" in out

    def test_asymmetric_play_in_output(self):
        out = self.fmt.format(_result(strategic_insight=self.si))
        assert "Lock in roaster contracts" in out

    def test_compound_trap_in_strategic_path(self):
        out = self.fmt.format(_result(strategic_insight=self.si, path=[_step()]))
        assert "Roaster relationship network" in out

    def test_kill_conditions_present(self):
        out = self.fmt.format(_result(strategic_insight=self.si))
        assert "Kill if" in out or "kill" in out.lower()

    def test_proceed_conditions_present(self):
        out = self.fmt.format(_result(strategic_insight=self.si))
        assert "Proceed when" in out or "proceed" in out.lower()

    def test_strategic_insight_via_param_overrides_result(self):
        result = _result(strategic_insight=None)
        si_override = {"asymmetric_play": "Injected play", "verdict": "Injected verdict"}
        out = self.fmt.format(result, strategic_insight=si_override)
        assert "Injected play" in out
        assert "Injected verdict" in out


# ── 3. Graceful degradation when strategic_insight is None ────────────────────


class TestStrategicInsightGraceful:
    def setup_method(self):
        self.fmt = OutputFormatter()

    def test_no_strategic_insight_no_crash(self):
        out = self.fmt.format(_result(strategic_insight=None))
        assert "# Intelligence Brief" in out

    def test_no_asymmetric_edge_section_when_no_si(self):
        out = self.fmt.format(_result(strategic_insight=None))
        assert "## Asymmetric Edge" not in out

    def test_mechanism_synthesized_from_dims_when_no_si(self):
        dims = {
            "market_size": _dim("market_size", score=0.9, zone="K"),
            "regulation": _dim("regulation", score=0.1, zone="?"),
        }
        out = self.fmt.format(_result(dim_scores=dims, strategic_insight=None))
        assert "## Mechanism" in out
        assert "market_size" in out or "regulation" in out

    def test_empty_result_no_crash(self):
        result = _result(dim_scores={}, gaps=[], path=[], strategic_insight=None)
        out = self.fmt.format(result)
        assert "# Intelligence Brief" in out


# ── 4. Gaps render as implications, not query lists ───────────────────────────


class TestGapImplications:
    def setup_method(self):
        self.fmt = OutputFormatter()

    def test_gap_section_present(self):
        out = self.fmt.format(_result(gaps=[_gap()]))
        assert "## Critical Gaps" in out

    def test_gap_shows_risk_level(self):
        high_gap = _gap(priority=0.9)
        out = self.fmt.format(_result(gaps=[high_gap]))
        assert "high" in out.lower()

    def test_gap_low_priority(self):
        low_gap = _gap(priority=0.2)
        out = self.fmt.format(_result(gaps=[low_gap]))
        assert "low" in out.lower()

    def test_gap_includes_implication_language(self):
        out = self.fmt.format(_result(gaps=[_gap()]))
        # Should say something about risk/decision/incomplete — implication, not just query list
        assert any(word in out.lower() for word in ["risk", "decision", "incomplete", "without"])

    def test_gap_does_not_just_list_missing_queries(self):
        gap = _gap()
        out = self.fmt.format(_result(gaps=[gap]))
        # The raw query strings like "who are competitors?" may or may not appear
        # but the format MUST include the suggested action wrapped in narrative context
        assert gap.suggested_action in out

    def test_no_gaps_no_section(self):
        out = self.fmt.format(_result(gaps=[]))
        assert "## Critical Gaps" not in out


# ── 5. Path renders as connected narrative ────────────────────────────────────


class TestPathNarrative:
    def setup_method(self):
        self.fmt = OutputFormatter()

    def test_path_section_present(self):
        out = self.fmt.format(_result(path=[_step()]))
        assert "## Strategic Path" in out

    def test_path_step_action_in_output(self):
        step = _step(action="Validate demand")
        out = self.fmt.format(_result(path=[step]))
        assert "Validate demand" in out

    def test_path_step_rationale_in_output(self):
        step = _step(rationale="No buyers = no business")
        out = self.fmt.format(_result(path=[step]))
        assert "No buyers = no business" in out

    def test_path_step_confidence_in_output(self):
        step = _step(conf=0.85)
        out = self.fmt.format(_result(path=[step]))
        assert "85%" in out

    def test_path_step_zone_tag_inline(self):
        step = _step(zone="T")
        out = self.fmt.format(_result(path=[step]))
        assert "[T]" in out

    def test_path_dependencies_shown(self):
        step = _step(deps=["market research", "legal review"])
        out = self.fmt.format(_result(path=[step]))
        assert "market research" in out

    def test_multi_step_path_all_steps_present(self):
        steps = [_step(n=1, action="Step A"), _step(n=2, action="Step B"), _step(n=3, action="Step C")]
        out = self.fmt.format(_result(path=steps))
        assert "Step A" in out
        assert "Step B" in out
        assert "Step C" in out

    def test_no_path_no_section(self):
        out = self.fmt.format(_result(path=[], strategic_insight=None))
        assert "## Strategic Path" not in out


# ── 6. Zone tags appear inline in landscape text ──────────────────────────────


class TestZoneTagsInline:
    def setup_method(self):
        self.fmt = OutputFormatter()

    def test_zone_K_in_landscape(self):
        dims = {"market_size": _dim(zone="K")}
        out = self.fmt.format(_result(dim_scores=dims))
        assert "[K]" in out

    def test_zone_T_in_landscape(self):
        dims = {"competition": _dim(zone="T")}
        out = self.fmt.format(_result(dim_scores=dims))
        assert "[T]" in out

    def test_zone_unknown_in_landscape(self):
        dims = {"regulation": _dim(zone="?")}
        out = self.fmt.format(_result(dim_scores=dims))
        assert "[?]" in out

    def test_contradictions_mentioned_in_landscape(self):
        dims = {"pricing": _dim(contradictions=3)}
        out = self.fmt.format(_result(dim_scores=dims))
        assert "contradiction" in out.lower() or "contested" in out.lower()

    def test_no_contradictions_no_contradiction_text(self):
        dims = {"pricing": _dim(contradictions=0)}
        out = self.fmt.format(_result(dim_scores=dims))
        assert "contradiction" not in out.lower()


# ── 7. Backward compatibility ─────────────────────────────────────────────────


class TestBackwardCompatibility:
    def setup_method(self):
        self.fmt = OutputFormatter()

    def test_format_with_no_extra_args(self):
        """Original callers pass only result — must still work."""
        result = _result()
        out = self.fmt.format(result)
        assert isinstance(out, str)
        assert len(out) > 50

    def test_format_with_strategic_insight_kwarg(self):
        out = self.fmt.format(_result(), strategic_insight={"verdict": "test"})
        assert "test" in out

    def test_format_with_founder_context_kwarg(self):
        """founder_context is accepted without error even if not yet used."""
        out = self.fmt.format(_result(), founder_context={"capital": 5000})
        assert isinstance(out, str)

    def test_format_returns_string(self):
        assert isinstance(self.fmt.format(_result()), str)

    def test_format_result_field_all_zones_zero(self):
        out = self.fmt.format(_result(facts_by_zone={}))
        assert "# Intelligence Brief" in out

    def test_meta_footer_has_query_type(self):
        out = self.fmt.format(_result(query_type="investment_thesis"))
        assert "investment_thesis" in out

    def test_meta_footer_has_fact_count(self):
        out = self.fmt.format(_result(facts_used=42))
        assert "42" in out
